const eventList = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/e/"]'));
  const events = [];
  const seen = new Set();

  for (const a of links) {
    const cleanUrl = a.href.split('?')[0];
    if (seen.has(cleanUrl)) continue;
    seen.add(cleanUrl);

    // Let's find the card container by traversing up until we find an element with significant text
    let container = a;
    while (container && container.parentElement && container.parentElement !== document.body) {
      if (container.parentElement.tagName === 'LI' || container.tagName === 'SECTION' || container.tagName === 'ARTICLE' || container.classList.contains('discover-search-desktop-card')) {
        break;
      }
      container = container.parentElement;
    }

    // Extract title, date, location, price, organizer
    // Let's look at all paragraphs, headings, spans
    const textBlocks = Array.from(container.querySelectorAll('h2, h3, p, span, div'))
      .map(el => el.textContent.trim())
      .filter(t => t.length > 0 && !t.startsWith('Save this event') && !t.startsWith('Share this event') && !t.includes('event actions'));

    // Or simply split container innerText
    const innerLines = container.innerText.split('\n').map(l => l.trim()).filter(Boolean);

    events.push({
      url: cleanUrl,
      innerLines
    });
  }
  return events;
});

