const parsedEvents = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('section.discover-horizontal-event-card, div.discover-horizontal-event-card, [class*="discover-search-desktop-card"]'));

  // Also collect all distinct event links
  const links = Array.from(document.querySelectorAll('a[href*="/e/"]'));
  const results = [];
  const seen = new Set();

  for (const a of links) {
    const cleanUrl = a.href.split('?')[0];
    if (seen.has(cleanUrl)) continue;
    seen.add(cleanUrl);

    // Get the card element
    let el = a;
    while (el && el.parentElement && !el.classList.contains('discover-search-desktop-card') && el.tagName !== 'LI') {
      el = el.parentElement;
    }
    const cardEl = el || a.parentElement;

    // Look for structured tags
    const title = cardEl.querySelector('h2, h3')?.textContent.trim() || '';

    // Get all text nodes or lines
    const rawText = cardEl.innerText;

    results.push({
      url: cleanUrl,
      title,
      rawText
    });
  }
  return results;
});

console.log("Found:", parsedEvents.length);
