  const seen = new Set();

  for (const a of links) {
    const cleanUrl = a.href.split('?')[0];
    if (seen.has(cleanUrl)) continue;
    seen.add(cleanUrl);

    let el = a;
    while (el && el.parentElement && !el.classList.contains('discover-search-desktop-card') && el.tagName !== 'LI') {
      el = el.parentElement;
    }
    const cardEl = el || a.parentElement;

    const rawText = cardEl.innerText;
    const lines = rawText.split('\n').map(s => s.trim()).filter(Boolean);

    // Let's check if it's promoted
    const isPromoted = lines.some(l => /promoted/i.test(l));

    results.push({
      url: cleanUrl,
      isPromoted,
      lines
    });
  }
  return results;
});

